import{z as l,x as n,o as e,c as i,q as A,j as B,D as a,d as s,s as r,S as o}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"窗口语义","description":"","frontmatter":{"title":"窗口语义","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/stream-windows.md","filePath":"cs/stream-windows.md","lastUpdated":1791413859000}'),d={name:"cs/stream-windows.md"};function p(c,E,m,h,C,_){const t=n("Mermaid");return e(),i("div",null,[E[2]||(E[2]=A('<h1 id="窗口语义" tabindex="-1">窗口语义 <a class="header-anchor" href="#窗口语义" aria-label="Permalink to &quot;窗口语义&quot;">​</a></h1><div class="epigraph"><p>窗口不是把流切成段的手段，而是把无界流变成无限多个有限关系的规则；规则没有说清的部分，聚合出来的每一个数都无从辩护。</p><footer>—— 据 Akidau et al., The Dataflow Model, VLDB 2015 整理</footer></div><p><a href="/cs/stream-model">上一课</a>把无界输入钉成带事件时间的记录与算子 DAG，但留了个缺口：聚合在无界流上没有自然的结束，每来一条记录，历史合计就得改一次。窗口是给聚合人为立边界的机制。本课钉窗口语义的四件套——指派、内容、发射、回收——的全部定义面；「何时可以放心关窗」是进度问题，留给下一课的 watermark。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>在无界流上问「昨天的下单量是多少」，隐含了按天切分，但引擎不知道。必须显式定义三件事：<strong>指派</strong>——每条记录属于哪个或哪些窗口，由事件时间的确定性函数决定；<strong>累积</strong>——窗口内的状态怎么随记录增长；<strong>发射</strong>——何时发、发几次、旧值怎么处理。不分开就出错：按处理时间切，重放重算结果不同；按事件时间切却不管迟到，关窗时刻是猜测；滑动窗口按「每条记录建独立窗」天真实现，状态量直接爆掉。会话窗更进一层：窗口边界本身依赖数据，晚到的记录可能把两个已关闭的窗并成一个。</p><p><span class="marginnote">滑动窗口的状态放大是可算的：大小 \\(s\\)、步长 \\(p\\) 的滑动窗，每个键同时活跃 \\(s/p\\) 个窗口。一小时窗、一分钟步长，就是每键六十个并行累加器——「窗口聚合」的内存账从这里起算，不是从记录数起算。</span></p><p><span class="marginnote">会话窗的直觉：每条记录先自己撑一顶小帐篷，若下一顶帐篷离得不超过 gap（比如 30 分钟无操作），就把两顶并成一顶——所以会话的个数与边界都不是预先定好的，而是数据自己长出来的；数据晚到，帐篷还会再并一次。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>指派。滚动窗口把事件时间轴切成不重叠的 \\([kt,\\; (k+1)t)\\)；滑动窗口允许重叠，一条记录进入 \\(s/p\\) 个窗；会话窗口先给每条记录一个孤立窗，空闲间隔不超过 gap 的窗在键内合并。累积：每键每窗一个累加器——计数可以直接合并，分位数要用可合并的草图，基数用 <a href="/cs/hyperloglog">HyperLogLog</a>，重数用 <a href="/cs/count-min-sketch">count-min</a>；累加器不可合并，窗口聚合就做不了并行。发射与累积模式绑定：丢弃式发增量，累积式发全量，累积加撤回式先收回旧值再发新值。撤回是会话窗与修订语义的硬前提：下游接不住撤回，就不能选这种模式。</p>',9)),(e(),B(o,null,{default:a(()=>[r(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20EVT%5B%22%E8%AE%B0%E5%BD%95%EF%BC%9A%E4%BA%8B%E4%BB%B6%E6%97%B6%E9%97%B4%20t%22%5D%20--%3E%20ASG%5B%22%E6%8C%87%E6%B4%BE%EF%BC%9A%E8%90%BD%E5%85%A5%E5%93%AA%E4%BA%9B%E7%AA%97%E5%8F%A3%22%5D%0A%20%20ASG%20--%3E%20ACC%5B%22%E6%AF%8F%E9%94%AE%E6%AF%8F%E7%AA%97%E7%B4%AF%E5%8A%A0%E5%99%A8%22%5D%0A%20%20ACC%20--%3E%20TRG%5B%22%E8%A7%A6%E5%8F%91%EF%BC%9A%E5%8F%91%E5%B0%84%20%2F%20%E6%92%A4%E5%9B%9E%E6%97%A7%E5%80%BC%22%5D%0A%20%20TRG%20--%3E%20OUT%5B%22%E7%BB%93%E6%9E%9C%20changelog%EF%BC%9A%E7%AA%97%E5%8F%A3%20%2B%20%E7%AC%AC%E5%87%A0%E6%AC%A1%E5%8F%91%E5%B0%84%22%5D%0A%20%20GC%5B%22%E8%BF%9B%E5%BA%A6%E5%A3%B0%E6%98%8E%E8%BF%87%E7%AA%97%22%5D%20--%3E%20EV%5B%22%E5%9B%9E%E6%94%B6%E7%AA%97%E5%8F%A3%E7%8A%B6%E6%80%81%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[s(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>窗口是把无限流变成无限多个有限关系的规则，所以状态的账是双重的：窗数与窗内容。活跃窗数由指派决定（滚动 \\(1\\)、滑动 \\(s/p\\)、会话随数据密度），窗内容由聚合器决定；两者都必须有回收条件，否则内存随运行时长线性涨——这与 <a href="/cs/mvcc-gc">MVCC 版本回收</a>是同一问题在两个层的形态：旧版本不回收，读性能与存储一起烂掉。会话窗的合并让「指派后可变」：合并触发撤回两个旧结果、发射一个新结果，序号要能对上。与 SQL <a href="/cs/window-functions">窗口函数</a>对照：那边 <code>OVER</code> 的行集有界且静态，聚合有天然结束；这边正是窗口让聚合获得指称上的结束。与时序库对照：<a href="/cs/timeseries-db">预聚合降采样</a>是滚动窗的物化特例。微批引擎把窗口绑在处理时间片上，实现简单，换掉的是事件时间正确性——重放即漂移。</p>',2)),(e(),B(o,null,{default:a(()=>[r(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E4%B8%80%E6%9D%A1%E4%BA%8B%E4%BB%B6%EF%BC%9A%E4%BA%8B%E4%BB%B6%E6%97%B6%E9%97%B4%20t%22%5D%20--%3E%20TU%5B%22%E6%BB%9A%E5%8A%A8%E7%AA%97%EF%BC%9A%E8%90%BD%E5%85%A5%201%20%E4%B8%AA%E7%AA%97%22%5D%0A%20%20E%20--%3E%20SL%5B%22%E6%BB%91%E5%8A%A8%E7%AA%97%EF%BC%9A%E5%90%8C%E6%97%B6%E8%90%BD%E5%85%A5%20s%2Fp%20%E4%B8%AA%E7%AA%97%22%5D%0A%20%20E%20--%3E%20SE%5B%22%E4%BC%9A%E8%AF%9D%E7%AA%97%EF%BC%9A%E5%85%88%E5%AD%A4%E7%AB%8B%EF%BC%8C%E5%86%8D%E6%8C%89%20gap%20%E5%90%88%E5%B9%B6%22%5D%0A%20%20TU%20--%3E%20G1%5B%22%E7%8A%B6%E6%80%81%E6%9C%80%E5%B0%8F%EF%BC%8C%E7%B2%92%E5%BA%A6%E5%9B%BA%E5%AE%9A%22%5D%0A%20%20SL%20--%3E%20G2%5B%22%E7%8A%B6%E6%80%81%E6%94%BE%E5%A4%A7%E7%BA%A6%20s%2Fp%20%E5%80%8D%22%5D%0A%20%20SE%20--%3E%20G3%5B%22%E8%BE%B9%E7%95%8C%E9%9A%8F%E6%95%B0%E6%8D%AE%E5%8F%98%EF%BC%8C%E9%9C%80%E6%92%A4%E5%9B%9E%E4%B8%8E%E5%90%88%E5%B9%B6%E6%92%91%E8%85%B0%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[s(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<p><span class="marginnote">撤回翻译成白话就是「先作废上一版，再报新版」：会话合并时，两个已发出的旧会话结果都要收回，改发一个合并后的新值——下游若存不下旧值或接不住「撤销」指令，这种累积模式就选不得。</span></p><p><span class="marginnote">常见误区：把窗口想成「把流剪成段」，段与段互不相干。实际上窗口是给每条记录贴窗号标签、按窗号各自累加——同一条记录在滑动窗下会同时出现在多个窗里，这也是状态要按「窗数 × 窗内容」双重计账的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课只谈指派、累积、发射三件套，不谈关窗的进度依据——那是 watermark 的定义域，迟到事件怎么处理也一并后置。端到端的恰好一次（窗口结果不因故障重发）在第四课。后课默认：每个窗口结果都带着「哪个窗、第几次发射」的坐标，且窗口状态有显式的回收条件；没有坐标的结果无法撤回，没有回收条件的窗口是泄漏。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>窗口语义四件套：指派、累积、发射、回收；少定义一件，结果就无从辩护。</li><li>滑动窗的状态放大是 \\(s/p\\) 倍；会话窗需要合并与撤回机制撑腰。</li><li>累加器必须可合并，窗口聚合才能并行；撤回能力决定可选的累积模式。</li><li>事件时间窗口让聚合有指称上的结束；处理时间窗口在重放下不成立。</li><li>出处：Akidau et al., The Dataflow Model, VLDB 2015；Streaming Systems, O&#39;Reilly 2018。</li></ul>',6))])}const F=l(d,[["render",p]]);export{f as __pageData,F as default};
